private boolean startsWith(ByteOrderMark bom, byte[] bytes) {
    byte[] bomBytes = bom.getBytes();
    if (bytes.length < bomBytes.length) {
        return false;
    }
    for (int i = 0; i < bomBytes.length; i++) {
        if (bomBytes[i] != bytes[i]) {
            return false;
        }
    }
    return true;
}
